function sortCivilopediaSidebarPanels(
	a: CivilopediaPageSidebarPanelDefinition,
	b: CivilopediaPageSidebarPanelDefinition,
): number {
	return a.SortIndex - b.SortIndex;
}

class PediaSidebarContent extends Component {
	private boundRefresh = this.doRefresh.bind(this);
	private sectionID: string | null = null;
	private pageID: string | null = null;
	private rafID = 0;

	onAttach(): void {
		this.sectionID = this.Root.getAttribute("data-section-id");
		this.pageID = this.Root.getAttribute("data-page-id");
		this.doRefresh();

		const panels: CivilopediaPageSidebarPanelDefinition[] = [];
		for (const panel of GameInfo.CivilopediaPageSidebarPanels) {
			if (
				(panel.SectionID == null || panel.SectionID == this.sectionID) &&
				(panel.PageID == null || panel.PageID == this.pageID)
			) {
				panels.push(panel);
			}
		}

		panels.sort(sortCivilopediaSidebarPanels);
	}

	onDetach() {
		if (this.rafID != 0) {
			cancelAnimationFrame(this.rafID);
			this.rafID = 0;
		}

		this.Root.innerHTML = "";
		this.sectionID = null;
		this.pageID = null;
	}

	onAttributeChanged(name: string, _oldValue: string | null, newValue: string | null): void {
		if (name == "data-section-id" && this.sectionID != newValue) {
			this.sectionID = newValue;
			this.queueRefresh();
		} else if (name == "data-page-id" && this.pageID != newValue) {
			this.pageID = newValue;
			this.queueRefresh();
		}
	}

	protected queueRefresh() {
		if (this.rafID == 0 && this.sectionID && this.pageID) {
			this.rafID = requestAnimationFrame(this.boundRefresh);
		}
	}

	private doRefresh() {
		this.rafID = 0;
		this.Root.innerHTML = "";

		if (this.pageID && this.sectionID) {
			const panels: CivilopediaPageSidebarPanelDefinition[] = [];
			for (const panel of GameInfo.CivilopediaPageSidebarPanels) {
				if (
					(panel.SectionID == null || panel.SectionID == this.sectionID) &&
					(panel.PageID == null || panel.PageID == this.pageID)
				) {
					panels.push(panel);
				}
			}

			panels.sort(sortCivilopediaSidebarPanels);

			const frag = document.createDocumentFragment();
			for (const p of panels) {
				const el = document.createElement(p.Component);

				if (this.sectionID) {
					el.setAttribute("data-section-id", this.sectionID);
				} else {
					el.removeAttribute("data-section-id");
				}

				if (this.pageID) {
					el.setAttribute("data-page-id", this.pageID);
				} else {
					el.removeAttribute("data-page-id");
				}

				frag.appendChild(el);
			}

			this.Root.appendChild(frag);
		}
	}
}

